// ---- reading the table ------------------------------------------------------
//  Hand-written below this line; the tables above are generated.

/// Which WHO table. Kept apart from GrowthMetric so this file depends on
/// nothing in the app.
enum WhoIndicator { weight, length, head }

List<WhoLms> _table(WhoIndicator i, bool boy) => switch (i) {
      WhoIndicator.weight => boy ? kWhoWeightBoys : kWhoWeightGirls,
      WhoIndicator.length => boy ? kWhoLengthBoys : kWhoLengthGirls,
      WhoIndicator.head => boy ? kWhoHeadBoys : kWhoHeadGirls,
    };

/// The oldest age the standards cover, in months.
const int kWhoMaxMonths = 60;

/// L, M, S at [ageMonths], linearly interpolated between whole months and
/// held at the ends (0 and 60).
WhoLms whoLms(WhoIndicator i, bool boy, double ageMonths) {
  final t = _table(i, boy);
  final a = ageMonths.clamp(0.0, kWhoMaxMonths.toDouble());
  final lo = a.floor();
  final hi = lo >= kWhoMaxMonths ? lo : lo + 1;
  final f = a - lo;
  final (l0, m0, s0) = t[lo];
  final (l1, m1, s1) = t[hi];
  return (l0 + (l1 - l0) * f, m0 + (m1 - m0) * f, s0 + (s1 - s0) * f);
}

/// The WHO z-score of [value].
double whoZ(WhoIndicator i, bool boy, double ageMonths, double value) {
  final (l, m, s) = whoLms(i, boy, ageMonths);
  if (value <= 0) return double.nan;
  if (l.abs() < 1e-6) return _ln(value / m) / s;
  return (_pow(value / m, l) - 1) / (l * s);
}

/// The value at z-score [z] (z = 0 is the median).
double whoValueAt(WhoIndicator i, bool boy, double ageMonths, double z) {
  final (l, m, s) = whoLms(i, boy, ageMonths);
  if (l.abs() < 1e-6) return m * _exp(s * z);
  final base = 1 + l * s * z;
  if (base <= 0) return 0;
  return m * _pow(base, 1 / l);
}

/// The share of children below z, as a percentile 0..100.
double whoPercentileOfZ(double z) => 50 * (1 + _erf(z / 1.4142135623730951));

// Abramowitz and Stegun 7.1.26, good to about 1.5e-7: plenty for a percentile
// that is shown rounded to the nearest five.
double _erf(double x) {
  final sign = x < 0 ? -1.0 : 1.0;
  final ax = x.abs();
  final t = 1 / (1 + 0.3275911 * ax);
  final y = 1 -
      (((((1.061405429 * t - 1.453152027) * t) + 1.421413741) * t - 0.284496736) * t + 0.254829592) *
          t *
          _exp(-ax * ax);
  return sign * y;
}

double _exp(double x) => math.exp(x);
double _ln(double x) => math.log(x);
double _pow(double x, double y) => math.pow(x, y).toDouble();
